(463546, 43882, 12733, '<td valign="top">Nice sharp shot with clean shadows. I like the way the tractor seems to emerge from the darkness.</td>', 'Nice sharp shot with clean shadows. I like the way the tractor seems to emerge from the darkness.', '2003-10-27 15:44:43.000000', NULL, 1),
