(463550, 44049, 12733, '<td valign="top">Great contrast between the dark and the light. Effective use of black and white.</td>', 'Great contrast between the dark and the light. Effective use of black and white.', '2003-10-27 15:49:24.000000', NULL, 1),
(463553, 43949, 12733, '<td valign="top">I like the way the shapes repeat in the open window and the shadow. The effect is interesting, and it would seem to require very good timing to get it just right.</td>', 'I like the way the shapes repeat in the open window and the shadow. The effect is interesting, and it would seem to require very good timing to get it just right.', '2003-10-27 15:53:02.000000', NULL, 1),
(463555, 43983, 4536, '<td valign="top">Nice clarity. A bit too static for my tastes, but still a nice photo, might make a good Christmas card.</td>', 'Nice clarity. A bit too static for my tastes, but still a nice photo, might make a good Christmas card.', '2003-10-27 15:54:25.000000', NULL, 1),
(463556, 43950, 10686, '<td valign="top">Interesting idea, great color, composition!!</td>', 'Interesting idea, great color, composition!!', '2003-10-27 15:56:20.000000', NULL, 1),
(463557, 43783, 4536, '<td valign="top">Nice idea. Would improve with a bit more contrast, blacks need to be blacker and whites need to be whiter.</td>', 'Nice idea. Would improve with a bit more contrast, blacks need to be blacker and whites need to be whiter.', '2003-10-27 15:57:08.000000', NULL, 1),
(463558, 43437, 10686, '<td valign="top">Looks like one of those candy rings. I like it. neat effect</td>', 'Looks like one of those candy rings. I like it. neat effect', '2003-10-27 15:57:28.000000', NULL, 1),
(463560, 44078, 10686, '<td valign="top">I like the contrast of the grid with the organic shapes of the shadows. The tone is a bit too much, maybe needs to be more subdued.</td>', 'I like the contrast of the grid with the organic shapes of the shadows. The tone is a bit too much, maybe needs to be more subdued.', '2003-10-27 15:59:18.000000', NULL, 1),
(463562, 43262, 10686, '<td valign="top">Very nice!!</td>', 'Very nice!!', '2003-10-27 16:00:06.000000', NULL, 1),
(463563, 44013, 12733, '<td valign="top">Interesting shadows - I like the way the color shows through. How do you get the upside-down effect?</td>', 'Interesting shadows - I like the way the color shows through. How do you get the upside-down effect?', '2003-10-27 16:00:07.000000', NULL, 1),
(463564, 43989, 10686, '<td valign="top">I like the idea, but the overall image seems kind of muddy</td>', 'I like the idea, but the overall image seems kind of muddy', '2003-10-27 16:00:50.000000', NULL, 1),
(463565, 44048, 10686, '<td valign="top">Subtle, but very funny. The front of the bottle is kind of dark though</td>', 'Subtle, but very funny. The front of the bottle is kind of dark though', '2003-10-27 16:01:52.000000', NULL, 1),
(463567, 43788, 10686, '<td valign="top">Nice idea, I think it would work better if the window/door on th right were cropped off.</td>', 'Nice idea, I think it would work better if the window/door on th right were cropped off.', '2003-10-27 16:03:00.000000', NULL, 1),
(463570, 43308, 10686, '<td valign="top">I like the suble tones of the background and the way the image is composed on it. It reminds me of a fossil plant.</td>', 'I like the suble tones of the background and the way the image is composed on it. It reminds me of a fossil plant.', '2003-10-27 16:04:31.000000', NULL, 1),
(463571, 44100, 10686, '<td valign="top">Good strong graphics, I think the bottom of the gate at the top of the image is distracting and the image would be stronger if it were cropped.</td>', 'Good strong graphics, I think the bottom of the gate at the top of the image is distracting and the image would be stronger if it were cropped.', '2003-10-27 16:05:49.000000', NULL, 1),
(463583, 44039, 173, '<td valign="top">Very cool shot. I would have liked to have seen it in mono B&amp;W to accent the shadows and maximize the contrast.</td>', 'Very cool shot. I would have liked to have seen it in mono B&W to accent the shadows and maximize the contrast.', '2003-10-27 16:25:16.000000', NULL, 1),
(463588, 43998, 3569, '<td valign="top">Nice shot.  blue works well.</td>', 'Nice shot.  blue works well.', '2003-10-27 16:27:57.000000', NULL, 1),
(463593, 43989, 3569, '<td valign="top">IMO the ornament appears to be a bit soft on focus.</td>', 'IMO the ornament appears to be a bit soft on focus.', '2003-10-27 16:30:48.000000', NULL, 1),
(463594, 44085, 7889, '<td valign="top">This is excellent but somehow i think it would have had more impact with just the single rose in the glass</td>', 'This is excellent but somehow i think it would have had more impact with just the single rose in the glass', '2003-10-27 16:31:38.000000', NULL, 1),
(463595, 44022, 3569, '<td valign="top">The wrinkles in the paper are somewhat distracting, otherwise, I like the idea.</td>', 'The wrinkles in the paper are somewhat distracting, otherwise, I like the idea.', '2003-10-27 16:31:42.000000', NULL, 1),
