(463602, 43985, 3569, '<td valign="top">I like the thought, but I would have made the spider larger or cropped the left a bit.  The colors and contrasts are great.</td>', 'I like the thought, but I would have made the spider larger or cropped the left a bit.  The colors and contrasts are great.', '2003-10-27 16:35:51.000000', NULL, 1),
(463607, 43997, 3569, '<td valign="top">I like the shot, but the blue is a bit too intence on the left sunface.</td>', 'I like the shot, but the blue is a bit too intence on the left sunface.', '2003-10-27 16:38:47.000000', NULL, 1),
(463610, 43523, 3569, '<td valign="top">Great interpretation.</td>', 'Great interpretation.', '2003-10-27 16:39:26.000000', NULL, 1),
(463611, 43716, 3569, '<td valign="top">Next time squash the post.  Otherwise nice...</td>', 'Next time squash the post.  Otherwise nice...', '2003-10-27 16:40:18.000000', NULL, 1),
(463612, 43129, 3569, '<td valign="top">Not sure what caused it or if on purpose, but the focus appears off, which lessens my score.</td>', 'Not sure what caused it or if on purpose, but the focus appears off, which lessens my score.', '2003-10-27 16:41:33.000000', NULL, 1),
(463614, 44046, 7889, '<td valign="top">one of my favourites - i like the idea very much and it works very well, good focus and colour and off course shadow. 8</td>', 'one of my favourites - i like the idea very much and it works very well, good focus and colour and off course shadow. 8', '2003-10-27 16:42:11.000000', NULL, 1),
(463616, 44039, 3569, '<td valign="top">Very cleaver.  Different colors would have been interesting too.  Nice.</td>', 'Very cleaver.  Different colors would have been interesting too.  Nice.', '2003-10-27 16:42:34.000000', NULL, 1),
(463617, 43995, 3569, '<td valign="top">Great shot.  It would have been hard not to sleep in church if there wasn''t a fire and brimstone minister.</td>', 'Great shot.  It would have been hard not to sleep in church if there wasn''t a fire and brimstone minister.', '2003-10-27 16:43:55.000000', NULL, 1),
(463618, 44067, 7889, '<td valign="top">Very interesting and unusual. Great patterns. 8</td>', 'Very interesting and unusual. Great patterns. 8', '2003-10-27 16:44:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(463619, 44088, 7889, '<td valign="top">You have put a lot of effort and thought into this and it works very well. 7</td>', 'You have put a lot of effort and thought into this and it works very well. 7', '2003-10-27 16:45:06.000000', NULL, 1),
(463620, 43648, 3569, '<td valign="top">Simple is good....</td>', 'Simple is good....', '2003-10-27 16:45:06.000000', NULL, 1),
(463622, 43923, 3569, '<td valign="top">Nice contrasts and gray shading.  Good job.</td>', 'Nice contrasts and gray shading.  Good job.', '2003-10-27 16:45:55.000000', NULL, 1),
(463623, 43727, 7889, '<td valign="top">Atmospheric and i love the colour of the door contrasting with the shadows. 8</td>', 'Atmospheric and i love the colour of the door contrasting with the shadows. 8', '2003-10-27 16:46:07.000000', NULL, 1),
(463625, 44023, 7889, '<td valign="top">Powerful and emotive. The use of only part of the face compliments makes this. 8</td>', 'Powerful and emotive. The use of only part of the face compliments makes this. 8', '2003-10-27 16:47:29.000000', NULL, 1),
(463626, 44044, 3569, '<td valign="top">Borned so we can live.  I like the shot except the dark bottom, which appears to cut of another nice shadow potential.</td>', 'Borned so we can live.  I like the shot except the dark bottom, which appears to cut of another nice shadow potential.', '2003-10-27 16:48:12.000000', NULL, 1),
(463627, 44087, 3569, '<td valign="top">A bit more contrast and ya got a winner.</td>', 'A bit more contrast and ya got a winner.', '2003-10-27 16:49:01.000000', NULL, 1),
(463628, 43950, 7889, '<td valign="top">What a great idea! I like how this works. 7</td>', 'What a great idea! I like how this works. 7', '2003-10-27 16:49:17.000000', NULL, 1),
(463629, 43970, 7889, '<td valign="top">Crisp focus, good shadow detail and excellent colour and lighthing. 8</td>', 'Crisp focus, good shadow detail and excellent colour and lighthing. 8', '2003-10-27 16:50:06.000000', NULL, 1),
(463630, 44059, 3569, '<td valign="top">IMO, the trees on top are to dark, thus drawing the eye away from the nice path portion.</td>', 'IMO, the trees on top are to dark, thus drawing the eye away from the nice path portion.', '2003-10-27 16:50:58.000000', NULL, 1),
