(463704, 43937, 12223, '<td valign="top">8. Wonderful.</td>', '8. Wonderful.', '2003-10-27 18:16:04.000000', NULL, 1),
(463705, 43580, 772, '<td valign="top">Shadows are present but I''m struggling to find interest.</td>', 'Shadows are present but I''m struggling to find interest.', '2003-10-27 18:16:23.000000', NULL, 1),
(463706, 43703, 12223, '<td valign="top">8. Creative.</td>', '8. Creative.', '2003-10-27 18:16:36.000000', NULL, 1),
(463708, 43129, 772, '<td valign="top">there''s a photograph in here somewhere :)</td>', 'there''s a photograph in here somewhere :)', '2003-10-27 18:16:55.000000', NULL, 1),
(463709, 43308, 12223, '<td valign="top">8. I like the texture.</td>', '8. I like the texture.', '2003-10-27 18:17:01.000000', NULL, 1),
