(464048, 44076, 11800, '<td valign="top">I had one prepared like this but decided it wasn''t in the spirit of the competition. Boy, am I ever going to feel stupid if this wins! I like the paper foreground and the parts that are touching and not touching. Good job.</td>', 'I had one prepared like this but decided it wasn''t in the spirit of the competition. Boy, am I ever going to feel stupid if this wins! I like the paper foreground and the parts that are touching and not touching. Good job.', '2003-10-27 23:04:57.000000', NULL, 1),
(464049, 43903, 10263, '<td valign="top">This took a lot of thought. Very creative.</td>', 'This took a lot of thought. Very creative.', '2003-10-27 23:05:04.000000', NULL, 1),
(464054, 43890, 11800, '<td valign="top">Nice light on the flower. It''s almost glowing and you didn''t blow any of it out. Very well shot. The shadow is a bit too long, maybe if the stem had been cut a little. The composition is too balanced which tends to make it not so exciting.</td>', 'Nice light on the flower. It''s almost glowing and you didn''t blow any of it out. Very well shot. The shadow is a bit too long, maybe if the stem had been cut a little. The composition is too balanced which tends to make it not so exciting.', '2003-10-27 23:12:05.000000', NULL, 1),
(464057, 44019, 10263, '<td valign="top">Absolutely gorgeous. Amazing capture.</td>', 'Absolutely gorgeous. Amazing capture.', '2003-10-27 23:18:11.000000', NULL, 1),
