(469813, 43589, 6624, '<td valign="top">I love the color flow, the yellow (light) line breaks it up a bit  8</td>', 'I love the color flow, the yellow (light) line breaks it up a bit  8', '2003-11-02 08:53:27.000000', NULL, 1),
(469816, 43951, 6624, '<td valign="top">nice approach, good colors - there are some reflections that are unfortunately eye-catching and the shadows are not as clear as they might be  also there is a black spot that is very unfortunate 6</td>', 'nice approach, good colors - there are some reflections that are unfortunately eye-catching and the shadows are not as clear as they might be  also there is a black spot that is very unfortunate 6', '2003-11-02 08:55:41.000000', NULL, 1),
(469818, 43983, 6624, '<td valign="top">the title is fun and the image is also fun - good shadows and clarity 8</td>', 'the title is fun and the image is also fun - good shadows and clarity 8', '2003-11-02 08:57:00.000000', NULL, 1),
(469819, 44078, 6624, '<td valign="top">I like this image a lot - the shadows that indeed make a painting, the background textures and color  there is a soft spot in the lower right that is unfortunate but overall the image gets a 8</td>', 'I like this image a lot - the shadows that indeed make a painting, the background textures and color  there is a soft spot in the lower right that is unfortunate but overall the image gets a 8', '2003-11-02 08:58:25.000000', NULL, 1),
(469820, 43308, 6624, '<td valign="top">This is a lovely shot...the shadow and textures are fine.  There might be too much black generalized shadow on bottom and left but the length of the stem is important to the composition - a 7</td>', 'This is a lovely shot...the shadow and textures are fine.  There might be too much black generalized shadow on bottom and left but the length of the stem is important to the composition - a 7', '2003-11-02 09:01:14.000000', NULL, 1),
(469821, 43638, 6624, '<td valign="top">gotta love Kokopelli...nice shadow image,  nicely composed, an 8</td>', 'gotta love Kokopelli...nice shadow image,  nicely composed, an 8', '2003-11-02 09:02:13.000000', NULL, 1),
(469822, 44087, 6624, '<td valign="top">nice shadow entry, nice color and sense of motion 7</td>', 'nice shadow entry, nice color and sense of motion 7', '2003-11-02 09:03:05.000000', NULL, 1),
(469823, 43923, 6624, '<td valign="top">nicely composed and executed, perhaps not the most original but good response to challenge 7</td>', 'nicely composed and executed, perhaps not the most original but good response to challenge 7', '2003-11-02 09:03:57.000000', NULL, 1),
(469824, 43693, 6624, '<td valign="top">interesting composition, color, concept 8</td>', 'interesting composition, color, concept 8', '2003-11-02 09:04:42.000000', NULL, 1),
(469825, 43394, 6624, '<td valign="top">nice shadow, nice flower - not so sure about the black and white surround 7</td>', 'nice shadow, nice flower - not so sure about the black and white surround 7', '2003-11-02 09:05:53.000000', NULL, 1),
(469828, 44080, 6624, '<td valign="top">beautiful light, hands, wrinkles, texture...nice composition 9</td>', 'beautiful light, hands, wrinkles, texture...nice composition 9', '2003-11-02 09:07:06.000000', NULL, 1),
(469829, 44049, 6624, '<td valign="top">very sweet, well titled, the detail is very nice 7</td>', 'very sweet, well titled, the detail is very nice 7', '2003-11-02 09:08:09.000000', NULL, 1),
(469830, 44085, 6624, '<td valign="top">interesting shadow , ood clarity..for me the white rose is a distraction from the main composition 6</td>', 'interesting shadow , ood clarity..for me the white rose is a distraction from the main composition 6', '2003-11-02 09:09:25.000000', NULL, 1),
(469831, 43944, 6624, '<td valign="top">interesting shot - I am not sure that light isn''t the real focus however...6</td>', 'interesting shot - I am not sure that light isn''t the real focus however...6', '2003-11-02 09:10:09.000000', NULL, 1),
(469832, 43797, 6624, '<td valign="top">I would have liked more crispness...interesting shadows thopugh 6</td>', 'I would have liked more crispness...interesting shadows thopugh 6', '2003-11-02 09:11:11.000000', NULL, 1),
(469833, 44019, 6624, '<td valign="top">very interesting shot - it is a little busy but the hadows are good 6</td>', 'very interesting shot - it is a little busy but the hadows are good 6', '2003-11-02 09:11:58.000000', NULL, 1),
(469834, 44039, 6624, '<td valign="top">very clever execution (all of it!)  there are some loose hairs or something that catch my eye on sides and bottom but a creative and interesting entry 8</td>', 'very clever execution (all of it!)  there are some loose hairs or something that catch my eye on sides and bottom but a creative and interesting entry 8', '2003-11-02 09:14:16.000000', NULL, 1),
(469835, 44002, 6624, '<td valign="top">if only the shadow were crisper...</td>', 'if only the shadow were crisper...', '2003-11-02 09:16:34.000000', NULL, 1),
(469836, 44076, 6624, '<td valign="top">this has the feel of a Japanese rice paper watercolor,,,6</td>', 'this has the feel of a Japanese rice paper watercolor,,,6', '2003-11-02 09:18:28.000000', NULL, 1),
(469837, 43949, 6624, '<td valign="top">nice capture..well-balanced composition</td>', 'nice capture..well-balanced composition', '2003-11-02 09:19:26.000000', NULL, 1),
(469838, 43221, 6624, '<td valign="top">beautiful crisp shadow nice weathered board texture 6</td>', 'beautiful crisp shadow nice weathered board texture 6', '2003-11-02 09:20:19.000000', NULL, 1),
(469861, 43262, 1031, '<td valign="top">Up close, nice detail. From far away, nice abstract. From across the room it looked like sand dunes ...</td>', 'Up close, nice detail. From far away, nice abstract. From across the room it looked like sand dunes ...', '2003-11-02 10:48:18.000000', NULL, 1),
(469865, 44059, 1031, '<td valign="top">A "classic" composition shot from an unusually low angle; good job keeping a "crispy" look even where it''s pretty dark and just out of the focal plane.</td>', 'A "classic" composition shot from an unusually low angle; good job keeping a "crispy" look even where it''s pretty dark and just out of the focal plane.', '2003-11-02 10:50:26.000000', NULL, 1),
(469867, 43989, 1031, '<td valign="top">I like the intricate shadow patterns, but I think the ornament(?) comes across by far as the dominant subject. Maybe shooting with the light at a lower angle or positioning the glass partly out of the frame would emphasize the shadows more.</td>', 'I like the intricate shadow patterns, but I think the ornament(?) comes across by far as the dominant subject. Maybe shooting with the light at a lower angle or positioning the glass partly out of the frame would emphasize the shadows more.', '2003-11-02 10:53:57.000000', NULL, 1),
(469869, 44025, 1031, '<td valign="top">Technically, I think you''ve reversed the challenge and are using a shadow to capture light, but you''ve done well at capturing both detail in the silhouette and color in the clouds with difficult backlighting conditions -- I try this a lot myself.</td>', 'Technically, I think you''ve reversed the challenge and are using a shadow to capture light, but you''ve done well at capturing both detail in the silhouette and color in the clouds with difficult backlighting conditions -- I try this a lot myself.', '2003-11-02 10:58:13.000000', NULL, 1),
(469887, 44080, 8953, '<td valign="top">Wonderful image.8</td>', 'Wonderful image.8', '2003-11-02 11:27:58.000000', NULL, 1),
(469888, 43919, 10402, '<td valign="top">Great low key portrait; just enough light to show the subject and put him in context as a saxophonist. The light on the edge of his hair brings out his outline and makes up for the side of his face being completely in shadow. Good background.</td>', 'Great low key portrait; just enough light to show the subject and put him in context as a saxophonist. The light on the edge of his hair brings out his outline and makes up for the side of his face being completely in shadow. Good background.', '2003-11-02 11:28:13.000000', NULL, 1),
(469890, 43919, 8953, '<td valign="top">An 8 from me:) focus just a tad bit soft still a fine use of light and shadow.</td>', 'An 8 from me:) focus just a tad bit soft still a fine use of light and shadow.', '2003-11-02 11:29:39.000000', NULL, 1),
(469893, 43262, 8953, '<td valign="top">so light, so elegant. lovely shadow and light effect.8</td>', 'so light, so elegant. lovely shadow and light effect.8', '2003-11-02 11:34:34.000000', NULL, 1),
(469895, 43935, 10402, '<td valign="top">My first impression was that the shadow across the model\''s face is distracting rather than appealing. But after taking the time to really look at the photo, I think it is beneficial. The larger shadow from the pole helps balance the shadow on her left side caused by the strong sunlight and the smaller shadows from the fence wire help show the contours of her face. Good composition and perfect cropping.</td>', 'My first impression was that the shadow across the model\''s face is distracting rather than appealing. But after taking the time to really look at the photo, I think it is beneficial. The larger shadow from the pole helps balance the shadow on her left side caused by the strong sunlight and the smaller shadows from the fence wire help show the contours of her face. Good composition and perfect cropping.', '2003-11-02 11:38:57.000000', NULL, 1),
(469906, 43867, 1031, '<td valign="top">At least on my monitor the light on her cheek looks a little harsh -- otherwise an excellently evocative portrait.</td>', 'At least on my monitor the light on her cheek looks a little harsh -- otherwise an excellently evocative portrait.', '2003-11-02 11:53:42.000000', NULL, 1),
(469908, 43589, 1031, '<td valign="top">I like the colors and curves. The angle is a little disorienting -- I wonder how it would look if the glass was blurred more to make the whole thing even more abstract.</td>', 'I like the colors and curves. The angle is a little disorienting -- I wonder how it would look if the glass was blurred more to make the whole thing even more abstract.', '2003-11-02 11:59:37.000000', NULL, 1),
(469911, 44003, 1031, '<td valign="top">Maybe more silhouette than show but very cool -- I look forward to reading about/seeing the set-up afterwards.</td>', 'Maybe more silhouette than show but very cool -- I look forward to reading about/seeing the set-up afterwards.', '2003-11-02 12:04:50.000000', NULL, 1),
(469913, 43903, 1031, '<td valign="top">That''s one clever use of office supplies!</td>', 'That''s one clever use of office supplies!', '2003-11-02 12:06:11.000000', NULL, 1),
(469920, 43648, 1031, '<td valign="top">Did it really say "Use light bulbs to photograph ..." Good control of lighting/reflections and DOF (extended DOF was a good choice here). Makes me want to play around with it in multiple color schemes -- maybe putting them all on one print pop-art style.</td>', 'Did it really say "Use light bulbs to photograph ..." Good control of lighting/reflections and DOF (extended DOF was a good choice here). Makes me want to play around with it in multiple color schemes -- maybe putting them all on one print pop-art style.', '2003-11-02 12:12:04.000000', NULL, 1),
(469923, 44014, 1031, '<td valign="top">Now why didn''t I think of that?</td>', 'Now why didn''t I think of that?', '2003-11-02 12:16:47.000000', NULL, 1),
(469926, 43437, 1031, '<td valign="top">Quite an unusual refractive effect! I''ll have to remember about that ...</td>', 'Quite an unusual refractive effect! I''ll have to remember about that ...', '2003-11-02 12:20:44.000000', NULL, 1),
(469935, 44088, 1031, '<td valign="top">That looks like a lot of work -- nice job!</td>', 'That looks like a lot of work -- nice job!', '2003-11-02 12:29:58.000000', NULL, 1),
(469938, 44067, 1031, '<td valign="top">Pretty spooky!</td>', 'Pretty spooky!', '2003-11-02 12:45:29.000000', NULL, 1),
(470008, 43499, 10402, '<td valign="top">Showing the backs of the flowers helps keep them from stealing the center of interest from their interesting shadows. Some sharpening would enhance the interesting textures of this image.</td>', 'Showing the backs of the flowers helps keep them from stealing the center of interest from their interesting shadows. Some sharpening would enhance the interesting textures of this image.', '2003-11-02 16:30:05.000000', NULL, 1),
(470010, 43417, 10402, '<td valign="top">Beautiful image with a great composition. The star filter is very effective here. The shadows are very subtle.</td>', 'Beautiful image with a great composition. The star filter is very effective here. The shadows are very subtle.', '2003-11-02 16:31:46.000000', NULL, 1),
(470012, 44100, 10402, '<td valign="top">The diagonal shadows make this a lot more interesting than a simple photo of littered pavement would be.</td>', 'The diagonal shadows make this a lot more interesting than a simple photo of littered pavement would be.', '2003-11-02 16:34:19.000000', NULL, 1),
(470017, 43997, 10402, '<td valign="top">An interesting object that, with two lights, casts a complex and interesting shadow.</td>', 'An interesting object that, with two lights, casts a complex and interesting shadow.', '2003-11-02 16:42:21.000000', NULL, 1),
(470018, 44050, 10402, '<td valign="top">Linking light and shadow gives this image a higher meaning. Very well executed. Although the bulb isn''t on, it is very well lit and the shadow is great.</td>', 'Linking light and shadow gives this image a higher meaning. Very well executed. Although the bulb isn''t on, it is very well lit and the shadow is great.', '2003-11-02 16:44:43.000000', NULL, 1),
(470024, 43394, 10402, '<td valign="top">The shadow is interesting, sharp, and the stark contrast with the white background makes it grab the viewer''s eye first. The flower is more subtle and doesn''t stand out as much from its dark background so doesn''t call immediate attention to itself, but is there to give an answer to the viewer''s inevitable question of what the shadow is from, and is interesting in its own right as well as adding a splash of needed color. This image works very well for me.</td>', 'The shadow is interesting, sharp, and the stark contrast with the white background makes it grab the viewer''s eye first. The flower is more subtle and doesn''t stand out as much from its dark background so doesn''t call immediate attention to itself, but is there to give an answer to the viewer''s inevitable question of what the shadow is from, and is interesting in its own right as well as adding a splash of needed color. This image works very well for me.', '2003-11-02 16:57:02.000000', NULL, 1),
(470027, 43937, 10402, '<td valign="top">The shadows are soft, yet so well defined that at first glance they look like part of the objects instead of shadows. Very subtle. I find the frame distracting.</td>', 'The shadows are soft, yet so well defined that at first glance they look like part of the objects instead of shadows. Very subtle. I find the frame distracting.', '2003-11-02 17:01:37.000000', NULL, 1),
(470030, 44076, 10402, '<td valign="top">You''ve done a great job of making the light and shadow look like the work of a talented artist. Perfect title.</td>', 'You''ve done a great job of making the light and shadow look like the work of a talented artist. Perfect title.', '2003-11-02 17:05:35.000000', NULL, 1),
(470033, 43129, 10402, '<td valign="top">Very artistic. One of the best uses of inversion I''ve seen.</td>', 'Very artistic. One of the best uses of inversion I''ve seen.', '2003-11-02 17:08:22.000000', NULL, 1),
(470036, 43783, 10402, '<td valign="top">Very creative. I like the effect. And the title.</td>', 'Very creative. I like the effect. And the title.', '2003-11-02 17:11:23.000000', NULL, 1),
(470040, 43903, 10978, '<td valign="top">WOW!!! That is very cool, and a super idea... a winner in my book.....10</td>', 'WOW!!! That is very cool, and a super idea... a winner in my book.....10', '2003-11-02 17:16:23.000000', NULL, 1),
(470041, 44005, 10978, '<td valign="top">LOL love this shot.... he looks very familiar.... 9 good luck!!</td>', 'LOL love this shot.... he looks very familiar.... 9 good luck!!', '2003-11-02 17:24:42.000000', NULL, 1),
(470042, 43577, 10978, '<td valign="top">I don''t really care for the grain to much. But i like the idea 5</td>', 'I don''t really care for the grain to much. But i like the idea 5', '2003-11-02 17:25:54.000000', NULL, 1),
(470044, 44039, 10978, '<td valign="top">That is just too cool!!!  7</td>', 'That is just too cool!!!  7', '2003-11-02 17:27:34.000000', NULL, 1),
(470048, 43821, 10402, '<td valign="top">A simple composition, but difficult to execute. You''ve balanced the fill lighting just right to illuminate the pear evenly without excessively diluting the nice sharp shadow from the key light. It would have been nice if the secondary shadow of the stem was hidden.</td>', 'A simple composition, but difficult to execute. You''ve balanced the fill lighting just right to illuminate the pear evenly without excessively diluting the nice sharp shadow from the key light. It would have been nice if the secondary shadow of the stem was hidden.', '2003-11-02 17:32:50.000000', NULL, 1),
(470050, 44013, 10978, '<td valign="top">I really like the colors, and great shadow. However, I am not sure about the shot set up. i think that you should have included the entire cup and shadow on the bottom, or not put any of it. The way it is now it kind of looks like it is...incomplete. Still good idea 6</td>', 'I really like the colors, and great shadow. However, I am not sure about the shot set up. i think that you should have included the entire cup and shadow on the bottom, or not put any of it. The way it is now it kind of looks like it is...incomplete. Still good idea 6', '2003-11-02 17:37:32.000000', NULL, 1),
(470052, 43221, 10402, '<td valign="top">The shadow is nice and sharp.</td>', 'The shadow is nice and sharp.', '2003-11-02 17:39:06.000000', NULL, 1),
(470055, 43889, 10402, '<td valign="top">Very unique use of shadow. Very effective. I can''t say I like it, but I can certainly appreciate it.</td>', 'Very unique use of shadow. Very effective. I can''t say I like it, but I can certainly appreciate it.', '2003-11-02 17:49:11.000000', NULL, 1),
(470058, 44045, 10402, '<td valign="top">Good composition. I think a sharper shadow would have been more effective.</td>', 'Good composition. I think a sharper shadow would have been more effective.', '2003-11-02 17:52:46.000000', NULL, 1),
(470103, 44076, 11078, '<td valign="top">I like this its a good idea and I like the colours</td>', 'I like this its a good idea and I like the colours', '2003-11-02 18:38:51.000000', NULL, 1),
(470121, 44048, 11078, '<td valign="top">clever</td>', 'clever', '2003-11-02 18:50:55.000000', NULL, 1),
(470137, 43693, 11078, '<td valign="top">This looks really professional and I am in awe yet again<br/>I dont think My camera can do this</td>', 'This looks really professional and I am in awe yet againI dont think My camera can do this', '2003-11-02 19:08:40.000000', NULL, 1),
(470140, 43417, 11078, '<td valign="top">This would be great for reflections nice workvery clear</td>', 'This would be great for reflections nice workvery clear', '2003-11-02 19:12:57.000000', NULL, 1),
(470156, 43686, 10625, '<td valign="top">i like how you''ve chosen to fill the frame on this particular angle.  good choice of subject</td>', 'i like how you''ve chosen to fill the frame on this particular angle.  good choice of subject', '2003-11-02 19:25:09.000000', NULL, 1),
(470159, 43983, 11078, '<td valign="top">Great idea and very clever</td>', 'Great idea and very clever', '2003-11-02 19:27:26.000000', NULL, 1),
(470161, 43950, 11078, '<td valign="top">very original and nicely done</td>', 'very original and nicely done', '2003-11-02 19:28:23.000000', NULL, 1),
(470165, 44039, 11078, '<td valign="top">Im glad I took a good look because it didnt look much on the thumb print <br/>Excellent idea well done!</td>', 'Im glad I took a good look because it didnt look much on the thumb print Excellent idea well done!', '2003-11-02 19:30:34.000000', NULL, 1),
(470254, 43589, 10263, '<td valign="top">Beautiful lines and colors</td>', 'Beautiful lines and colors', '2003-11-02 21:14:24.000000', NULL, 1),
(470256, 44005, 10263, '<td valign="top">Very creative.. made me smile :) Not crazy about the blue though</td>', 'Very creative.. made me smile :) Not crazy about the blue though', '2003-11-02 21:16:57.000000', NULL, 1),
(470274, 43935, 10263, '<td valign="top">Beautiful child. She must have been eating chocolate... or mud lol</td>', 'Beautiful child. She must have been eating chocolate... or mud lol', '2003-11-02 21:38:06.000000', NULL, 1),
(470278, 44050, 6771, '<td valign="top">Very interseting.  Nice work on the light and shadow without blowing everything out.  Like to see it bit brighter, though.</td>', 'Very interseting.  Nice work on the light and shadow without blowing everything out.  Like to see it bit brighter, though.', '2003-11-02 21:42:33.000000', NULL, 1),
(470281, 44039, 6771, '<td valign="top">This is definitely the most original out of them all!   Excellent and creative idea.  I am wondering if brighter light would have created stronger shadows, but then that could blow out the block.  Some hair or noise on the grey area. Might be cool to retry this one with "seamless" edges on the box in all white.</td>', 'This is definitely the most original out of them all!   Excellent and creative idea.  I am wondering if brighter light would have created stronger shadows, but then that could blow out the block.  Some hair or noise on the grey area. Might be cool to retry this one with "seamless" edges on the box in all white.', '2003-11-02 21:46:02.000000', NULL, 1),
(470283, 43523, 6771, '<td valign="top">Very ingenious idea.  Works well all the way around</td>', 'Very ingenious idea.  Works well all the way around', '2003-11-02 21:46:54.000000', NULL, 1),
(470288, 43993, 6771, '<td valign="top">Excelent use and creative shadow.  Like to see longer DOF to have the pumpkin and shadow in focus.</td>', 'Excelent use and creative shadow.  Like to see longer DOF to have the pumpkin and shadow in focus.', '2003-11-02 21:49:07.000000', NULL, 1),
(470289, 43903, 6771, '<td valign="top">what a great idea and tribute.  Like to see you redo it with studio set up.  Something under the buildings other that a table, etc.  I think that would give it much more impact.  Like the laser light...nice touch</td>', 'what a great idea and tribute.  Like to see you redo it with studio set up.  Something under the buildings other that a table, etc.  I think that would give it much more impact.  Like the laser light...nice touch', '2003-11-02 21:51:06.000000', NULL, 1),
(470290, 43893, 6771, '<td valign="top">Great use of negative space.  Shadow works well and makes it look like a chain link necklace.</td>', 'Great use of negative space.  Shadow works well and makes it look like a chain link necklace.', '2003-11-02 21:52:47.000000', NULL, 1),
(470296, 44050, 13773, '<td valign="top">Which came first, the title or the idea?</td>', 'Which came first, the title or the idea?', '2003-11-02 21:55:52.000000', NULL, 1),
(470310, 43308, 5318, '<td valign="top">Nice use of light here,shadow definitly stands out. Love the texture ,it almost takes on its own shadow,anyway great background....10</td>', 'Nice use of light here,shadow definitly stands out. Love the texture ,it almost takes on its own shadow,anyway great background....10', '2003-11-02 22:03:34.000000', NULL, 1),
(470314, 44004, 7485, '<td valign="top">Seasonal, yet most unusual, nice!</td>', 'Seasonal, yet most unusual, nice!', '2003-11-02 22:08:19.000000', NULL, 1),
(470316, 43867, 13773, '<td valign="top">The nearly invisible objects obove her head look like horns and make her seem very demonic</td>', 'The nearly invisible objects obove her head look like horns and make her seem very demonic', '2003-11-02 22:10:45.000000', NULL, 1),
(470317, 44080, 7485, '<td valign="top">Great photo, beautiful textures (both skin and cloth), but not all that interesting shadows...</td>', 'Great photo, beautiful textures (both skin and cloth), but not all that interesting shadows...', '2003-11-02 22:11:14.000000', NULL, 1),
(470319, 43867, 7485, '<td valign="top">Spooky! I particularly like the subtle glints in the background, they add mystery. Although one of them makes her look like she has a horn (normally not good!), here it is oddly appropriate.</td>', 'Spooky! I particularly like the subtle glints in the background, they add mystery. Although one of them makes her look like she has a horn (normally not good!), here it is oddly appropriate.', '2003-11-02 22:16:02.000000', NULL, 1),
(470320, 44023, 7485, '<td valign="top">Great concept! She is very well lit, but wish the shadow were slightly crisper.</td>', 'Great concept! She is very well lit, but wish the shadow were slightly crisper.', '2003-11-02 22:18:13.000000', NULL, 1),
(470323, 43890, 7485, '<td valign="top">Good idea, but the shadow needs to be crisper</td>', 'Good idea, but the shadow needs to be crisper', '2003-11-02 22:20:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(470324, 43921, 7485, '<td valign="top">Very, very nice. But when you put a copy on DPCprints, consider spot-editing out that pebble (or wrapper?) just below center.</td>', 'Very, very nice. But when you put a copy on DPCprints, consider spot-editing out that pebble (or wrapper?) just below center.', '2003-11-02 22:24:16.000000', NULL, 1),
(470330, 43950, 7485, '<td valign="top">Brilliant idea, I think we have a winner here</td>', 'Brilliant idea, I think we have a winner here', '2003-11-02 22:27:07.000000', NULL, 1),
(470334, 43893, 7485, '<td valign="top">I really love a good abstract, but this is just a little too pure for me. Maybe a closer crop?</td>', 'I really love a good abstract, but this is just a little too pure for me. Maybe a closer crop?', '2003-11-02 22:28:58.000000', NULL, 1),
(470339, 43954, 7485, '<td valign="top">Excellent composition, but I''d have rotated the image to either make the lines truly vertical or more tilted</td>', 'Excellent composition, but I''d have rotated the image to either make the lines truly vertical or more tilted', '2003-11-02 22:32:18.000000', NULL, 1),
(470349, 44076, 7969, '<td valign="top">My choice for the blue, I think this shot is stunning, the tones, the soft feel, it looks and feels like a painting or charcoal drawing.  Wonderful execution.  Truly delightful to behold!!</td>', 'My choice for the blue, I think this shot is stunning, the tones, the soft feel, it looks and feels like a painting or charcoal drawing.  Wonderful execution.  Truly delightful to behold!!', '2003-11-02 22:51:33.000000', NULL, 1),
